#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const cp=require('node:child_process');
const crypto=require('node:crypto');
const PATHS=Object.freeze({installDir:'/opt/prhm-deployhq-control',server:'/opt/prhm-deployhq-control/server.js',unit:'/etc/systemd/system/prhm-deployhq-control.service',backupRoot:'/var/backups/prhm-deployhq-control-v1',emailSource:'/etc/prhm-credentials/deployhq/email',apiKeySource:'/etc/prhm-credentials/deployhq/api-key'});
const SOURCE=path.join(__dirname,'deployhq-control-adapter-v1.js');
function fp12(b){return crypto.createHash('sha256').update(b).digest('hex').slice(0,12)}
function checkCredential(file,stat,readFile){let st;try{st=stat(file)}catch(e){if(e&&e.code==='ENOENT')throw new Error('deployhq_credential_source_missing');throw e}if(!st.isFile()||st.uid!==0)throw new Error('deployhq_credential_source_owner_invalid');if((st.mode&0o077)!==0)throw new Error('deployhq_credential_source_mode_invalid');const b=readFile(file);if(!b||!b.length)throw new Error('deployhq_credential_source_empty');return {length:b.length,fingerprint:fp12(b)}}
function preflight({stat=fs.statSync,readFile=fs.readFileSync}={}){const e=checkCredential(PATHS.emailSource,stat,readFile),k=checkCredential(PATHS.apiKeySource,stat,readFile);return {ok:true,action:'deployhq_control_adapter_v1',preflight_only:true,production_mutation:false,credential_present:true,email_length:e.length,api_key_length:k.length,email_fingerprint:e.fingerprint,api_key_fingerprint:k.fingerprint}}
function renderUnit(){return `[Unit]\nDescription=PRHM DeployHQ Control Adapter\nAfter=network-online.target\nWants=network-online.target\n\n[Service]\nType=simple\nDynamicUser=true\nStateDirectory=prhm-deployhq-control\nWorkingDirectory=/opt/prhm-deployhq-control\nExecStart=/usr/local/bin/prhm-node /opt/prhm-deployhq-control/server.js --serve\nLoadCredential=deployhq_email:/etc/prhm-credentials/deployhq/email\nLoadCredential=deployhq_api_key:/etc/prhm-credentials/deployhq/api-key\nNoNewPrivileges=true\nPrivateTmp=true\nProtectSystem=strict\nProtectHome=true\nProtectKernelTunables=true\nProtectKernelModules=true\nProtectControlGroups=true\nRestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX\nRestrictSUIDSGID=true\nLockPersonality=true\nMemoryDenyWriteExecute=true\nUMask=0077\nRestart=on-failure\nRestartSec=2s\n\n[Install]\nWantedBy=multi-user.target\n`}
function atomicWrite(file,data,mode=0o644){const dir=path.dirname(file);fs.mkdirSync(dir,{recursive:true,mode:0o755});const tmp=file+'.tmp-'+process.pid;fs.writeFileSync(tmp,data,{mode});fs.chmodSync(tmp,mode);fs.renameSync(tmp,file)}
function systemctl(args){cp.execFileSync('/usr/bin/systemctl',args,{stdio:'pipe',timeout:60000})}
function apply(){const pf=preflight();if(!fs.existsSync(SOURCE))throw new Error('adapter_source_missing');const stamp=new Date().toISOString().replace(/[:.]/g,'-');const backup=path.join(PATHS.backupRoot,stamp);fs.mkdirSync(backup,{recursive:true,mode:0o700});const journal={backup,server_existed:fs.existsSync(PATHS.server),unit_existed:fs.existsSync(PATHS.unit)};if(journal.server_existed)fs.copyFileSync(PATHS.server,path.join(backup,'server.js'));if(journal.unit_existed)fs.copyFileSync(PATHS.unit,path.join(backup,'prhm-deployhq-control.service'));try{atomicWrite(PATHS.server,fs.readFileSync(SOURCE),0o755);atomicWrite(PATHS.unit,renderUnit(),0o644);systemctl(['daemon-reload']);systemctl(['enable','--now','prhm-deployhq-control.service']);return {...pf,preflight_only:false,production_mutation:true,backup_path:backup}}catch(e){rollback(journal);throw e}}
function rollback(journal){try{if(journal.server_existed)fs.copyFileSync(path.join(journal.backup,'server.js'),PATHS.server);else fs.rmSync(PATHS.server,{force:true});if(journal.unit_existed)fs.copyFileSync(path.join(journal.backup,'prhm-deployhq-control.service'),PATHS.unit);else fs.rmSync(PATHS.unit,{force:true});systemctl(['daemon-reload']);return {rollback_performed:true}}catch(e){throw Object.assign(new Error('rollback_failed'),{cause:e})}}
function main(){const args=process.argv.slice(2);if(args.length===1&&args[0]==='--preflight-only'){console.log(JSON.stringify(preflight()));return}if(args.length===0){console.log(JSON.stringify(apply()));return}throw new Error('unexpected_arguments')}
if(require.main===module){try{main()}catch(e){console.error(JSON.stringify({ok:false,error:e.message}));process.exit(1)}}
module.exports={PATHS,renderUnit,preflight,apply,rollback};
